package com.booksyde.controller; import com.booksyde.dto.request.CreateVolumeRequest; import com.booksyde.dto.response.VolumeResponse; import com.booksyde.service.*; import jakarta.validation.Valid; import java.util.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1") public class VolumeController {private final VolumeService volumes; private final AuthenticatedUserService users; public VolumeController(VolumeService volumes,AuthenticatedUserService users){this.volumes=volumes;this.users=users;} @GetMapping("/books/{bookId}/volumes") public List<VolumeResponse> list(@PathVariable UUID bookId,@AuthenticationPrincipal Jwt jwt){var u=users.resolve(jwt);return volumes.list(bookId,u.id(),u.roles());} @PostMapping("/books/{bookId}/volumes") public VolumeResponse create(@PathVariable UUID bookId,@Valid @RequestBody CreateVolumeRequest r,@AuthenticationPrincipal Jwt jwt){var u=users.resolve(jwt);return volumes.create(bookId,r,u.id(),u.roles());} @DeleteMapping("/volumes/{id}") public void delete(@PathVariable UUID id,@AuthenticationPrincipal Jwt jwt){var u=users.resolve(jwt);volumes.delete(id,u.id(),u.roles());}}
